    // Match exacto por nombre + dirección
    if (expectedDirection) {
      const exactMatch = categoryMap[`${categoria}__${expectedDirection}`];

      if (exactMatch) {
        categoryId = exactMatch.id;
        matchedBy = "name+direction";
        matchedCategoryDirection = exactMatch.direction;
      }
